export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (amountCents <= 0) throw new Error('amount must be positive')
  const balance = getBalance(ledger, from)
  if (balance < amountCents) throw new Error('insufficient funds')
  const ts = hooks.clock?.() ?? Date.now()
  ledger.append({ type: 'debit', account: from, amountCents, ts, id: hooks.nextId?.() ?? `evt-${ledger.eventCount()}` })
  ledger.append({ type: 'credit', account: to, amountCents, ts, id: hooks.nextId?.() ?? `evt-${ledger.eventCount()}` })
  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

args.new_string:
export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (!Number.isSafeInteger(amountCents) || amountCents <= 0) {
    throw new Error('amount must be positive')
  }
  const balance = getBalance(ledger, from)
  if (balance < amountCents) throw new Error('insufficient funds')

  // Prepare everything that can invoke caller code before changing the ledger.
  // In particular, a failing second nextId call must not leave an unmatched
  // debit in the event stream.
  const ts = hooks.clock?.() ?? Date.now()
  const firstSeq = ledger.eventCount()
  const debitId = hooks.nextId?.() ?? `evt-${firstSeq}`
  const creditId = hooks.nextId?.() ?? `evt-${firstSeq + 1}`

  ledger.append({ type: 'debit', account: from, amountCents, ts, id: debitId })
  ledger.append({ type: 'credit', account: to, amountCents, ts, id: creditId })
  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

