/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */
const ledgerStates = new WeakMap()

function validateEvent(event, expectedType) {
  if (event?.type !== expectedType) {
    throw new Error(`event type must be ${expectedType}`)
  }
  if (!Number.isSafeInteger(event.amountCents) || event.amountCents <= 0) {
    throw new Error('amount must be positive')
  }
}

function storedEvent(event, seq) {
  return Object.freeze({ ...event, seq })
}

export function createLedger() {
  const state = {
    events: [],
    balances: new Map(),
    fundingOpen: true,
  }

  const ledger = {
    append(event) {
      validateEvent(event, 'credit')
      if (!state.fundingOpen) throw new Error('initial funding is closed')

      const current = state.balances.get(event.account) ?? 0
      const next = current + event.amountCents
      if (!Number.isSafeInteger(next)) throw new Error('balance exceeds safe integer range')

      state.events.push(storedEvent(event, state.events.length))
      state.balances.set(event.account, next)
    },
    eventCount() {
      return state.events.length
    },
    fold() {
      const balances = new Map()
      for (const event of state.events) {
        const current = balances.get(event.account) ?? 0
        const delta = event.type === 'credit' ? event.amountCents : -event.amountCents
        balances.set(event.account, current + delta)
      }
      return Object.fromEntries(balances)
    },
    events() {
      return state.events.map((event) => ({ ...event }))
    },
  }

  ledgerStates.set(ledger, state)
  return ledger
}

export function appendTransfer(ledger, debit, credit) {
  const state = ledgerStates.get(ledger)
  if (state === undefined) throw new Error('invalid ledger')
  validateEvent(debit, 'debit')
  validateEvent(credit, 'credit')
  if (debit.amountCents !== credit.amountCents) {
    throw new Error('transfer events must conserve funds')
  }

  const senderBalance = state.balances.get(debit.account) ?? 0
  if (senderBalance < debit.amountCents) throw new Error('insufficient funds')

  const recipientBalance = state.balances.get(credit.account) ?? 0
  const recipientAfterDebit = debit.account === credit.account
    ? recipientBalance - debit.amountCents
    : recipientBalance
  const recipientNext = recipientAfterDebit + credit.amountCents
  if (!Number.isSafeInteger(recipientNext)) throw new Error('balance exceeds safe integer range')

  const firstSeq = state.events.length
  const storedDebit = storedEvent(debit, firstSeq)
  const storedCredit = storedEvent(credit, firstSeq + 1)
  state.events.push(storedDebit, storedCredit)
  state.balances.set(debit.account, senderBalance - debit.amountCents)
  state.balances.set(credit.account, recipientNext)
  state.fundingOpen = false
}

