export function createRebateHook(ledger, ratePercent) {
  if (!Number.isSafeInteger(ratePercent) || ratePercent < 0 || ratePercent >= 100) {
    throw new Error('rebate rate must be an integer from 0 to 99')
  }

  const hook = ({ from, to, amountCents }) => {
    const rebate = Math.floor((amountCents * ratePercent) / 100)
    if (!Number.isSafeInteger(rebate)) throw new Error('rebate exceeds safe integer range')
    if (rebate === 0) return
    transfer(ledger, to, from, rebate, { onSettled: hook })
  }
  return hook
}

